/**
 * Blog 列表页与详情页模板（从 console.whaleal.com/blog 迁移，2026-11-24）。
 *
 * 由 gatsby-node.js 的 createPages 从 src/data/blog.js 生成：
 *   /blog/          列表
 *   /blog/<slug>/   5 篇详情
 *
 * 🟢 2026-11-26：正文数据 src/data/blog.js 的 title/excerpt/blocks[].v 已补齐
 *    10 语，路由走 config 的 LOCALIZED_DYNAMIC_PAGES（blog 由 createPages 生成，
 *    没有 src/pages/blog.js，故不能进 LOCALIZED_PAGES —— 那里会做文件存在性校验）。
 *    内链与 canonical 统一走 localePath，与 hreflang 声明同源，不再出现
 *    「/zh/blog/ 是规范页但站内没有链接指向它」的自相矛盾。
 * 🔴 BSP §6：正文中的 failover / 分段计费 / 渠道质量看板均写在 SMS 语境，
 *    渲染时不改写、不泛化到三通道。
 *
 * @since 2026-11-24
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { POSTS } from '../data/blog';
import { MESSAGING_PRODUCT_NAME } from '../constants/brand';
import '../styles/marketing.css';
import { usePageI18n } from '../i18n';
import { localePath } from '../i18n/config';

const CAT_LABEL = {
  en: { PRODUCT: 'Product', ENGINEERING: 'Engineering', INDUSTRY: 'Industry', COMPLIANCE: 'Compliance' },
  zh: { PRODUCT: '产品思考', ENGINEERING: '工程实践', INDUSTRY: '行业观察', COMPLIANCE: '合规实践' },
  de: { PRODUCT: 'Produkt', ENGINEERING: 'Technik', INDUSTRY: 'Branche', COMPLIANCE: 'Compliance' },
  fr: { PRODUCT: 'Produit', ENGINEERING: 'Ingénierie', INDUSTRY: 'Secteur', COMPLIANCE: 'Conformité' },
  es: { PRODUCT: 'Producto', ENGINEERING: 'Ingeniería', INDUSTRY: 'Sector', COMPLIANCE: 'Cumplimiento' },
  ja: { PRODUCT: 'プロダクト', ENGINEERING: 'エンジニアリング', INDUSTRY: '業界', COMPLIANCE: 'コンプライアンス' },
  it: { PRODUCT: 'Prodotto', ENGINEERING: 'Ingegneria', INDUSTRY: 'Settore', COMPLIANCE: 'Conformità' },
  pt: { PRODUCT: 'Produto', ENGINEERING: 'Engenharia', INDUSTRY: 'Setor', COMPLIANCE: 'Conformidade' },
  ko: { PRODUCT: '제품', ENGINEERING: '엔지니어링', INDUSTRY: '업계', COMPLIANCE: '컴플라이언스' },
  'zh-Hant': { PRODUCT: '產品思維', ENGINEERING: '工程實踐', INDUSTRY: '產業觀察', COMPLIANCE: '合規實踐' },
};

// 产品名按正文语言选：中文页用「鲸联 Platform」，其余语言保留英文常量（品牌名不译）。
const CJK_LOCALES = new Set(['zh', 'zh-Hant']);
const platformName = (lang) => (CJK_LOCALES.has(lang) ? '鲸联' : MESSAGING_PRODUCT_NAME);

/** 按语言取双语/多语字段，缺该语时回退英文（英文是契约真源）。 */
function pick(bilingual, lang) {
  if (!bilingual) return '';
  return bilingual[lang] || bilingual.en || '';
}

const UI = {
  readPost: { en: 'Read the post →', zh: '阅读全文 →', de: 'Beitrag lesen →', fr: 'Lire l’article →', es: 'Leer el artículo →', ja: '記事を読む →', it: 'Leggi l’articolo →', pt: 'Ler o artigo →', ko: '글 읽기 →', 'zh-Hant': '閱讀全文 →' },
  blog: { en: 'Blog', zh: '博客', de: 'Blog', fr: 'Blog', es: 'Blog', ja: 'ブログ', it: 'Blog', pt: 'Blog', ko: '블로그', 'zh-Hant': '部落格' },
  home: { en: 'Home', zh: '首页', de: 'Startseite', fr: 'Accueil', es: 'Inicio', ja: 'ホーム', it: 'Home', pt: 'Início', ko: '홈', 'zh-Hant': '首頁' },
  title: { en: 'Blog', zh: '博客', de: 'Blog', fr: 'Blog', es: 'Blog', ja: 'ブログ', it: 'Blog', pt: 'Blog', ko: '블로그', 'zh-Hant': '部落格' },
  desc: {
    en: 'Engineering notes and product thinking on BYOL messaging, SMS failover, delivery receipts and compliance.',
    zh: '关于 BYOL 消息架构、短信故障转移、送达回执与合规的工程笔记与产品思考。',
    de: 'Technische Notizen und Produktgedanken zu BYOL-Messaging, SMS-Failover, Zustellungsbestätigungen und Compliance.',
    fr: 'Notes techniques et réflexions produit sur la messagerie BYOL, le basculement SMS, les accusés de réception et la conformité.',
    es: 'Notas de ingeniería y reflexiones de producto sobre mensajería BYOL, failover de SMS, acuses de recepción y cumplimiento.',
    ja: 'BYOL メッセージング、SMS フェイルオーバー、配信レシート、コンプライアンスに関する技術ノートとプロダクト思考。',
    it: 'Note tecniche e riflessioni sul prodotto relative a messaggistica BYOL, failover SMS, ricevute di consegna e conformità.',
    pt: 'Notas de engenharia e reflexões de produto sobre mensageria BYOL, failover de SMS, recibos de entrega e conformidade.',
    ko: 'BYOL 메시징, SMS 장애 조치, 전달 영수증 및 컴플라이언스에 관한 기술 노트와 제품 생각.',
    'zh-Hant': '關於 BYOL 訊息架構、簡訊故障轉移、送達回執與合規的工程筆記與產品思考。',
  },
  heroTitle: { en: 'Notes from the messaging layer', zh: '来自消息层的笔记', de: 'Notizen aus der Messaging-Schicht', fr: 'Notes de la couche de messagerie', es: 'Notas desde la capa de mensajería', ja: 'メッセージング層からのノート', it: 'Note dal livello di messaggistica', pt: 'Notas da camada de mensageria', ko: '메시징 레이어에서 온 노트', 'zh-Hant': '來自訊息層的筆記' },
  heroLead: { en: 'Engineering notes, product thinking and compliance practice from the team behind Whaleal.', zh: '来自鲸联团队的工程笔记、产品思考与合规实践。', de: 'Technische Notizen, Produktgedanken und Compliance-Praxis vom Team hinter Whaleal.', fr: 'Notes techniques, réflexions produit et pratiques de conformité de l’équipe derrière Whaleal.', es: 'Notas de ingeniería, reflexiones de producto y prácticas de cumplimiento del equipo detrás de Whaleal.', ja: 'Whaleal を支えるチームによる技術ノート、プロダクト思考、コンプライアンス実践。', it: 'Note tecniche, riflessioni sul prodotto e pratiche di conformità del team dietro Whaleal.', pt: 'Notas de engenharia, reflexões de produto e práticas de conformidade da equipe por trás da Whaleal.', ko: 'Whaleal 팀의 기술 노트, 제품 생각, 컴플라이언스 실천.', 'zh-Hant': '來自鯨聯團隊的工程筆記、產品思考與合規實踐。' },
  keepReading: { en: 'Keep reading', zh: '继续阅读', de: 'Weiterlesen', fr: 'À lire aussi', es: 'Seguir leyendo', ja: '続けて読む', it: 'Continua a leggere', pt: 'Continue lendo', ko: '계속 읽기', 'zh-Hant': '繼續閱讀' },
};

function PostCard({ post, lang }) {
  // 🔴 内链与 canonical/hreflang 同读 localePath（LOCALIZED_DYNAMIC_PAGES 已放行
  //    /blog/*），避免出现「/zh/blog/<slug>/ 是规范页但站内无链接指向它」的漂移。
  const postHref = localePath(`/blog/${post.slug}/`, lang);
  return (
    <article className="mk-card">
      <span className="mk-card-tag">{post.date} · {(CAT_LABEL[lang] || CAT_LABEL.en)[post.cat] || post.cat}</span>
      <h3><Link to={postHref}>{pick(post.title, lang)}</Link></h3>
      <p>{pick(post.excerpt, lang)}</p>
      <Link className="mk-card-link" to={postHref}>{pick(UI.readPost, lang)}</Link>
    </article>
  );
}

function BlogIndex({ pageContext }) {
  const { locale } = usePageI18n(pageContext);
  const lang = locale || 'en';
  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={`${pick(UI.title, lang)} — ${platformName(lang)}`}
        description={pick(UI.desc, lang)}
        pathname="/blog/"
        // 🔴 canonical 自引用：与各语真实路由同源（blog 在 LOCALIZED_DYNAMIC_PAGES，
        //    localePath 会正确加前缀），避免非英文页被判成英文副本。
        canonicalPath={localePath('/blog/', lang)}
        softwareApp={false}
        breadcrumbs={[
          { name: pick(UI.home, lang), path: localePath('/', lang) },
          { name: pick(UI.blog, lang), path: localePath('/blog/', lang) },
        ]}
        hrefLang={lang}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{pick(UI.blog, lang)}</span>
          <h1>{pick(UI.heroTitle, lang)}</h1>
          <p className="mk-lead">{pick(UI.heroLead, lang)}</p>
        </header>
        <section className="mk-section">
          <div className="mk-grid">
            {POSTS.map((post) => <PostCard key={post.slug} post={post} lang={lang} />)}
          </div>
        </section>
      </div>
    </Layout>
  );
}

function BlogPost({ pageContext }) {
  const { locale } = usePageI18n(pageContext);
  const lang = locale || 'en';
  const post = pageContext.post;
  const more = POSTS.filter((p) => p.slug !== post.slug).slice(0, 3);
  const postPath = `/blog/${post.slug}/`;
  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={`${pick(post.title, lang)} — ${platformName(lang)}`}
        description={pick(post.excerpt, lang)}
        pathname={postPath}
        canonicalPath={localePath(postPath, lang)}
        softwareApp={false}
        ogType="article"
        // BlogPosting 与页面 h1 / lead / meta 描述同源；日期取 POSTS[].date，
        // 10 语各自产出一条（headline 与 inLanguage 随语言变化）。
        article={{
          headline: pick(post.title, lang),
          description: pick(post.excerpt, lang),
          datePublished: post.date,
        }}
        breadcrumbs={[
          { name: pick(UI.home, lang), path: localePath('/', lang) },
          { name: pick(UI.blog, lang), path: localePath('/blog/', lang) },
          { name: pick(post.title, lang), path: localePath(postPath, lang) },
        ]}
        hrefLang={lang}
      />
      <div className="mk">
        <article className="mk-section narrow">
          <p className="mk-meta">{post.date} · {(CAT_LABEL[lang] || CAT_LABEL.en)[post.cat] || post.cat}</p>
          <h1>{pick(post.title, lang)}</h1>
          {post.blocks.map((b, i) => {
            if (b.t === 'h2') return <h2 key={i}>{pick(b.v, lang)}</h2>;
            if (b.t === 'quote') return <blockquote key={i}>{pick(b.v, lang)}</blockquote>;
            if (b.t === 'code') return <pre key={i}>{pick(b.v, lang)}</pre>;
            return <p className="mk-section-lead" key={i}>{pick(b.v, lang)}</p>;
          })}
        </article>
        <section className="mk-section">
          <h2>{pick(UI.keepReading, lang)}</h2>
          <div className="mk-grid">
            {more.map((p) => <PostCard key={p.slug} post={p} lang={lang} />)}
          </div>
        </section>
      </div>
    </Layout>
  );
}

/** Gatsby 入口：按 pageContext.kind 分发列表 / 详情（两页共用一个模板文件）。 */
export default function BlogTemplate(props) {
  return props.pageContext.kind === 'post'
    ? <BlogPost {...props} />
    : <BlogIndex {...props} />;
}
